import { spfi, SPFx as spSPFx } from "@pnp/sp";
import "@pnp/sp/webs";
import "@pnp/sp/lists";
import "@pnp/sp/search";

const normalizeUrl = (url: any): string =>
    (url || "").toString().toLowerCase().replace(/\/+$/, "");

/**
 * Build Sites filter UI from SmartMetadata (TaxType Sites / Sites Old).
 * Groups by Parent.Title (SP / IPPF / mbeon) — same shape as HHHHQA search path.
 */
export function buildActiveSitesFromMetadata(allRootMetaData: any[]): any[] {
    const siteItems = (allRootMetaData || []).filter((meta: any) => {
        if (!meta) return false;
        const tax = meta.TaxType;
        if (tax !== "Sites" && tax !== "Sites Old") return false;
        if (meta.IsVisible === false || meta.IsVisible === 0 || meta.IsVisible === "0") return false;
        return Boolean(meta.listId && meta.Title);
    });

    const grouped: Record<string, any> = {};
    siteItems.forEach((meta: any) => {
        const groupTitle = meta?.Parent?.Title || meta?.siteName || meta?.Title || "Sites";
        const key = String(groupTitle).toLowerCase();
        const siteUrl = meta.originalSiteUrl || meta.siteUrl || "";
        if (!grouped[key]) {
            grouped[key] = {
                Site: {
                    Title: groupTitle,
                    Url: siteUrl,
                    SiteId: meta.SiteId || "",
                    WebId: meta.WebId || ""
                },
                TaskLists: [] as any[]
            };
        } else if (siteUrl && !grouped[key].Site.Url) {
            grouped[key].Site.Url = siteUrl;
        }

        const already = grouped[key].TaskLists.some(
            (t: any) =>
                (t.Id && meta.listId && t.Id.toLowerCase() === meta.listId.toLowerCase()) ||
                (t.Title && meta.Title && t.Title.toLowerCase() === meta.Title.toLowerCase())
        );
        if (already) return;

        const coverObj =
            meta?.Item_x005F_x0020_Cover ||
            meta?.Item_x0020_Cover ||
            meta?.coverImage ||
            null;

        grouped[key].TaskLists.push({
            Title: meta.Title,
            Id: meta.listId,
            Url: siteUrl
                ? `${siteUrl.replace(/\/+$/, "")}/Lists/${encodeURIComponent(meta.Title)}`
                : "",
            Item_x005F_x0020_Cover: coverObj,
            Item_x0020_Cover: coverObj,
            coverImage: coverObj
        });
    });

    return Object.keys(grouped)
        .map((k) => grouped[k])
        .filter((g) => g.TaskLists?.length > 0);
}

async function getFilteredTaskLists(activeSites: any, allRootMetaData: any) {
    const result: any = [];
    activeSites?.forEach((siteObj: any) => {
        const siteUrlNorm = normalizeUrl(siteObj.Site?.Url);
        const matchingRootItems = (allRootMetaData || []).filter((meta: any) => {
            if (!meta) return false;
            const metaUrlNorm = normalizeUrl(meta.siteUrl || meta.originalSiteUrl);
            return Boolean(metaUrlNorm && siteUrlNorm && metaUrlNorm === siteUrlNorm);
        });

        if (!matchingRootItems.length) return;

        const matchedTaskLists: any = [];
        siteObj?.TaskLists?.forEach((taskList: any) => {
            const matchedMeta = matchingRootItems.find((meta: any) => {
                if (meta.listId && taskList.Id && meta.listId.toLowerCase() === String(taskList.Id).toLowerCase()) {
                    return true;
                }
                return Boolean(
                    meta.Title &&
                    taskList.Title &&
                    meta.Title.toLowerCase() === String(taskList.Title).toLowerCase()
                );
            });
            if (matchedMeta) {
                const coverObj =
                    matchedMeta.Item_x005F_x0020_Cover ||
                    matchedMeta.Item_x0020_Cover ||
                    matchedMeta.coverImage ||
                    null;
                matchedTaskLists.push({
                    ...taskList,
                    Item_x005F_x0020_Cover: coverObj,
                    Item_x0020_Cover: coverObj,
                    coverImage: coverObj
                });
            }
        });

        if (matchedTaskLists.length > 0) {
            result.push({
                Site: siteObj.Site,
                TaskLists: matchedTaskLists
            });
        }
    });
    return result;
}

export async function getSubsitesForRoot({ spContext, AllRootMetaData }: any) {
    if (!spContext) {
        console.error("[FetchDynamicActiveSites] Missing SPFx context");
        return buildActiveSitesFromMetadata(AllRootMetaData);
    }

    const sp = spfi().using(spSPFx(spContext));
    const rawUrl =
        spContext?.pageContext?.web?.absoluteUrl ||
        (typeof window !== "undefined" ? window.location.href : "");
    const rootUrl = rawUrl
        ? rawUrl.match(/^(https?:\/\/[^\/]+\/sites\/[^\/\?#]+)/i)?.[1] ||
        rawUrl.replace(/\/+$/, "")
        : "https://hhhhteams.sharepoint.com/sites/HHHH";

    // Step 1: Get webs under the site collection (HHHHQA parity)
    let subsites: any[] = [];
    try {
        const subsiteResults = await sp.search({
            Querytext: `Path:${rootUrl}* contentclass:STS_Web`,
            RowLimit: 100,
            SelectProperties: ["Title", "Path", "SiteId", "WebId"]
        });
        subsites = (subsiteResults?.PrimarySearchResults || []).map((r: any) => ({
            Title: r.Title,
            Url: r.Path,
            SiteId: r.SiteId,
            WebId: r.WebId
        }));
    } catch (err) {
        console.error("[FetchDynamicActiveSites] Error searching subsites:", err);
    }

    // Also include unique siteUrls from Sites metadata (covers webs search may miss)
    const urlSet = new Set(subsites.map((s) => normalizeUrl(s.Url)));
    (AllRootMetaData || []).forEach((meta: any) => {
        if (
            (meta?.TaxType === "Sites" || meta?.TaxType === "Sites Old") &&
            meta?.siteUrl &&
            !urlSet.has(normalizeUrl(meta.siteUrl))
        ) {
            urlSet.add(normalizeUrl(meta.siteUrl));
            subsites.push({
                Title: meta?.Parent?.Title || meta?.siteName || meta?.Title,
                Url: meta.siteUrl,
                SiteId: "",
                WebId: ""
            });
        }
    });

    // Step 2: For each web, fetch Task lists (BaseTemplate 171 — HHHHQA parity)
    const siteTasks = await Promise.all(
        subsites.map(async (site) => {
            try {
                const siteSp = spfi(site.Url).using(spSPFx(spContext));
                const lists = await siteSp.web.lists();
                const taskLists = lists?.filter((l: any) => l.BaseTemplate === 171);
                const excludedTitles: string[] = [
                    "Offshore Tasks",
                    "Master Tasks",
                    "DRR",
                    "SDC Sites",
                    "QA",
                    "Foundation",
                    "Health",
                    "Gender",
                    "SP Online"
                ];
                const activeTaskList = taskLists?.filter(
                    (taskList: any) =>
                        taskList?.Title !== undefined && !excludedTitles.includes(taskList.Title)
                );
                return {
                    Site: site,
                    TaskLists: activeTaskList?.map((l: any) => ({
                        Title: l.Title,
                        Id: l.Id,
                        Url: `${site.Url}/Lists/${encodeURIComponent(l.Title)}`
                    }))
                };
            } catch (e) {
                console.log(`Error fetching lists for ${site.Url}`, e);
                return { Site: site, TaskLists: [] };
            }
        })
    );

    const AllRootSites = (AllRootMetaData || []).filter(
        (root: any) => root?.TaxType === "Sites" || root?.TaxType === "Sites Old"
    );
    const activesitesTasks = siteTasks?.filter((e) => e.TaskLists?.length > 0);
    let activeTAsklist = await getFilteredTaskLists(activesitesTasks, AllRootSites);

    // Prefer search+list path when it produced sites (HHHHQA behavior)
    if (activeTAsklist?.length > 0) {
        return activeTAsklist;
    }

    // Reliable fallback: SmartMetadata Sites grouped like the working QA UI
    const fromMeta = buildActiveSitesFromMetadata(AllRootMetaData);
    if (fromMeta.length > 0) {
        return fromMeta;
    }

    return activeTAsklist || [];
}

    return (
        <div className="w-full space-y-3">
            {/* ── Sites Section ── */}
            <div className="mb-2">
                <details className="group">
                    <summary className="flex items-center justify-between cursor-pointer select-none py-3 px-4 rounded-lg bg-white border border-gray-200 text-slate-800 font-medium text-sm transition-all list-none shadow-sm mb-4">
                        <span className="flex items-center gap-3">
                            <ChevronRight className="w-5 h-5 text-[#2f5597] transition-transform group-open:rotate-90" />
                            <span className="text-[#2f5597] font-semibold text-base">Sites</span>
                        </span>
                        <div className="flex items-center gap-4">
                            {useForOMTTool === true && (
                                <span onClick={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }} onMouseDown={e => { e.stopPropagation(); e.nativeEvent.stopImmediatePropagation(); }}>
                                    <Tooltip ComponentId={15962} />
                                </span>
                            )}
                        </div>
                    </summary>

                    <label className={`${checkboxLabelCls} mt-2 px-2`}>
                        <input type="checkbox" className={checkboxCls} checked={allSelectedSites} onChange={handleSelectAllSites} />
                        <span className={checkboxTextCls}>Select All</span>
                    </label>

                    <div className="mb-3 mt-1.5 space-y-3 px-2">
                        {activeSites?.map((siteData: any, siteIndex: any) => (
                            <div key={siteIndex} className="mb-3">
                                {/* Site Title with Checkbox */}
                                <div className="flex items-center mb-2 pb-1 border-b border-slate-100">
                                    <input
                                        type="checkbox"
                                        id={`site-${siteIndex}`}
                                        className={`${checkboxCls} mr-2`}
                                        checked={selectedSiteTitles?.includes(siteData?.Site?.Url)}
                                        onChange={e => handleIndividualSitesChange(siteData?.Site?.Url, e.target.checked, siteData)}
                                    />
                                    <label className="text-xs font-semibold text-slate-800 cursor-pointer hover:text-blue-600 transition-colors" htmlFor={`site-${siteIndex}`}>
                                        {siteData.Site.Title}
                                    </label>
                                </div>
                                {/* Task Lists — Avatar circles */}
                                <div className="flex flex-wrap gap-2 ml-3">
                                    {siteData?.TaskLists?.map((taskList: any, taskIndex: any) => {
                                        const coverUrl = getCoverImageUrl(taskList);
                                        const isSelected = isTaskListSelected(taskList.Id);
                                        return (
                                            <div
                                                key={taskIndex}
                                                onClick={() => handleTaskListSelect(siteData, taskList)}
                                                className="relative cursor-pointer"
                                                title={taskList.Title}
                                            >
                                                <div
                                                    className={`w-[26px] h-[26px] rounded-full flex items-center justify-center relative transition-all ${isSelected ? 'ring-2 ring-blue-600 scale-105 shadow-md' : 'ring-1 ring-slate-200 shadow-sm hover:scale-105 hover:ring-blue-300'}`}
                                                    style={{ backgroundColor: coverUrl ? 'transparent' : getRandomColor(taskList.Id) }}
                                                >
                                                    {coverUrl ? (
                                                        <img src={coverUrl} alt={taskList.Title} className="w-[22px] h-[22px] rounded-full object-cover" />
                                                    ) : (
                                                        <span className="text-white font-bold text-[9px]">{getInitials(taskList.Title)}</span>
                                                    )}
                                                </div>
                                                {isSelected && (
                                                    <div className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-blue-600 rounded-full flex items-center justify-center border border-white shadow">
                                                        <i className="text-white text-[7px] not-italic font-bold">✓</i>
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        ))}
                    </div>
                </details>
            </div>

            {/* ── Result Type Section ── */}
            {(useForOMTTool === undefined || useForOMTTool === null || useForOMTTool === false) && (
                <div className="mb-2">
                    <details className="group" open>
                        <summary className="flex items-center justify-between cursor-pointer select-none py-2 px-2.5 rounded-lg bg-slate-100/80 hover:bg-slate-200/60 text-slate-800 font-semibold text-xs uppercase tracking-wider transition-all list-none">
                            <span>Result type</span>
                        </summary>

                        {/* Select All */}
                        <label className={`${checkboxLabelCls} mt-2 px-2`}>
                            <input
                                type="checkbox"
                                className={checkboxCls}
                                checked={standaloneSelectAll}
                                onChange={e => handleStandaloneSelectAll(e.target.checked)}
                            />
                            <span className={checkboxTextCls}>Select All</span>
                        </label>

                        {/* Document types */}
                        {(ContextValue?.useForOnlyTasks === undefined || ContextValue?.useForOnlyTasks != true) && (
                            <div className="mt-1 px-2">
                                {allFileTypeRefiners?.length > 0 && Object.keys(documentTypes)?.length > 0 && (
                                    <div className="mb-2">
                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
                                            <input type="checkbox" className={checkboxCls} checked={documentSelectAll} onChange={e => handleDocumentSelectAll(e.target.checked)} />
                                            <span className={checkboxTextCls}>DOCUMENT</span>
                                        </label>
                                        <div className="flex flex-col gap-1 border-l-2 border-slate-200 pl-3 ml-3 my-1.5">
                                            {Object.keys(documentTypes)?.map(type => (
                                                <label key={type} className={checkboxLabelCls}>
                                                    <input type="checkbox" className={checkboxCls} checked={documentTypes[type]} onChange={e => handleDocumentTypeChange(type, e.target.checked)} />
                                                    <span className={checkboxTextCls}>{type.toUpperCase()}</span>
                                                </label>
                                            ))}
                                        </div>
                                    </div>
                                )}
                                {allFileTypeRefiners?.length === 0 && (
                                    <div className="mb-2">
                                        <label className={`${checkboxLabelCls} font-semibold text-slate-800`}>
                                            <input type="checkbox" className={checkboxCls} checked={resultTypeAllDoc} onChange={e => setResultTypesAllDoc(e.target.checked)} />
                                            <span className={checkboxTextCls}>DOCUMENT</span>
                                        </label>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Task / Portfolio / Project */}
                        <div className="flex flex-col gap-1 px-2 mt-1">
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Task} onChange={e => handleStandaloneTypeChange('Task', e.target.checked)} />
                                <span className={checkboxTextCls}>TASK (AWT)</span>
                            </label>
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Portfolio} onChange={e => handleStandaloneTypeChange('Portfolio', e.target.checked)} />
                                <span className={checkboxTextCls}>PORTFOLIO (CSF)</span>
                            </label>
                            <label className={checkboxLabelCls}>
                                <input type="checkbox" className={checkboxCls} checked={standaloneTypes.Project} onChange={e => handleStandaloneTypeChange('Project', e.target.checked)} />
                                <span className={checkboxTextCls}>PROJECT</span>
                            </label>
                        </div>
                    </details>
                </div>
            )}
        </div>
    );
};

export default ResultTypeFilter;

