    // Cache key is hub-metadata only (not task-user source) so arriving
    // parent roster later does not re-fan-out SmartMetadata.
    const cacheKey = `${rootSiteUrl}|${(rootSiteData || []).map((s: any) => `${s?.siteUrl || ''}:${s?.SmartMetadataListID || s?.metadataListId || ''}`).join(',')}`;

    const applyCached = (cached: NonNullable<typeof ootbRootMetaCache>) => {
        sitesData = cached.allMetaData?.filter((item: any) => item?.TaxType === 'Sites Old' || item?.TaxType === "Sites") || [];
        AllRootMetaData = [...(cached.allMetaData || [])];
        const liveUsers = parentTaskUsers || cached.userData || [];
        AllRootUsersData = [...liveUsers];
        masterTasksSiteData = cached.masterTasksSiteData || rootSiteData;
        CurrentUserInfo = AllRootUsersData?.find((elem: any) => elem?.AssingedToUser?.Id === spfxContext?.pageContext?.legacyPageContext?.userId) || cached.currentUserInfo;
        setTaskUsers(AllRootUsersData);
        setActiveSites(cached.activeSites || []);
        if (queryString?.current?.length > 0) {
            runSearch(sortBy);
        }
        setLoaded(true);
    };

    if (ootbRootMetaCache?.key === cacheKey) {
        applyCached(ootbRootMetaCache);
        return;
    }
    if (ootbRootMetaInFlight) {
        const pending = await ootbRootMetaInFlight;
        if (pending?.key === cacheKey) {
            applyCached(pending);
            return;
        }
    }

    ootbRootMetaInFlight = (async () => {
        const userData: any = parentTaskUsers ? [...parentTaskUsers] : [];
        const metaFilter =
            "(TaxType eq 'Sites') or (TaxType eq 'Sites Old') or (TaxType eq 'Priority') or (TaxType eq 'Percent Complete')";
        // One SmartMetadata GET per unique listId; skip hubs OMT already excludes.
        const seenMetaLists = new Set<string>();
        const hubs = (rootSiteData || []).filter((site: any) => {
            const name = String(site?.siteName || site?.Title || '').toLowerCase();
            if (name === 'ksl' || name === 'smartmanagement') return false;
            const listId = site?.SmartMetadataListID || site?.metadataListId;
            const url = String(site?.siteUrl || '').replace(/\/+$/, '').toLowerCase();
            if (!listId || !url) return false;
            const key = `${url}|${listId}`;
            if (seenMetaLists.has(key)) return false;
            seenMetaLists.add(key);
            return true;
        });

        const sitesDataPromises = hubs.map(async (site: any) => {
            const webSvc = new Web(site.siteUrl);
            try {
                const metaListId = site?.SmartMetadataListID || site?.metadataListId;
                let metaData: any = await webSvc.lists.getById(metaListId).items
                    .select("Id", "Title", "IsVisible", "ParentID", "SmartSuggestions", "TaxType", "Configurations", "Item_x005F_x0020_Cover", "listId", "siteName", "siteUrl", "SortOrder", "SmartFilters", "Selectable", "Color_x0020_Tag", "Parent/Id", "Parent/Title")
                    .expand("Parent")
                    .filter(metaFilter)
                    .top(4999)
                    .get();
                // Only fetch Task Users when parent did not supply them — and only from the first hub that succeeds.
                if (!parentTaskUsers && userData.length === 0 && site?.TaskUserListID) {
                    try {
                        const taskUsersRows = await webSvc.lists.getById(site.TaskUserListID).items
                            .select("Id", "Email", "Suffix", "Title", "Item_x0020_Cover", "AssingedToUserId", "AssingedToUser/Title", "AssingedToUser/EMail", "AssingedToUser/Id", "AssingedToUser/Name", "UserGroup/Id", "ItemType")
                            .expand("AssingedToUser", "UserGroup")
                            .get();
                        if (taskUsersRows?.length) {
                            userData.push(...taskUsersRows);
                        }
                    } catch (tuErr) {
                        console.warn("[OOTB Search OMT] Task Users skipped for", site?.siteUrl, tuErr);
                    }
                }
                metaData?.forEach((item: any) => {
                    item.originalSiteUrl = item.siteUrl || site.siteUrl;
                    item.siteUrl = site.siteUrl;
                    if (item.Configurations && (item.TaxType === "Sites" || item.TaxType === "Sites Old")) {
                        try {
                            const configArr = typeof item.Configurations === 'string' ? JSON.parse(item.Configurations) : item.Configurations;
                            if (Array.isArray(configArr) && configArr.length > 0) {
                                const conf = configArr[0];
                                item.listId = item.listId || conf.listId;
                                item.siteName = item.siteName || conf.siteName || conf.Title || item.Title;
                                if (conf.siteUrl) {
                                    item.originalSiteUrl = conf.siteUrl;
                                    item.siteUrl = conf.siteUrl;
                                }
                                item.Item_x005F_x0020_Cover = item.Item_x005F_x0020_Cover || conf.ImageUrl || conf.Item_x005F_x0020_Cover;
                                item.Item_x0020_Cover = item.Item_x0020_Cover || conf.ImageUrl || conf.Item_x0020_Cover;
                            }
                        } catch (e) {
                            console.error("Error parsing Configurations for site item", e);
                        }
                    }
                });
                return metaData;
            } catch (error) {
                console.error("[OOTB Search OMT] Failed loading metadata for", site?.siteUrl, error);
                return [];
            }
        });

        let sitesArrays: any = await Promise.all(sitesDataPromises.map((p: Promise<any[]>) => p.catch((): any[] => [])));
        sitesArrays = sitesArrays?.filter((v: any) => Array.isArray(v));
        const allMetaData = sitesArrays?.reduce((acc: any, val: any) => acc.concat(val), []) || [];
        let activeSitesss = await getSubsitesForRoot({ spContext: spfxContext, AllRootMetaData: allMetaData });
        if (!activeSitesss || activeSitesss.length === 0) {
            activeSitesss = buildActiveSitesFromMetadata(allMetaData);
        }
        const currentUserInfo = userData?.find((elem: any) => elem?.AssingedToUser?.Id === spfxContext?.pageContext?.legacyPageContext?.userId);
        const cached = {
            key: cacheKey,
            allMetaData,
            userData,
            activeSites: activeSitesss || [],
            masterTasksSiteData: rootSiteData,
            currentUserInfo,
        };
        ootbRootMetaCache = cached;
        return cached;
    })();

    try {
        const cached = await ootbRootMetaInFlight;
        if (cached) applyCached(cached);
        else setLoaded(true);
    } finally {
        ootbRootMetaInFlight = null;
    }
} catch (error) {

